import React, { useEffect, useState } from "react";
import ajax from "@/utils/ajax";
import { 
  Select,
  Input,
  Button,
  Spin,
  Avatar,
  Message,
  Skeleton,
  Typography 
} from "@arco-design/web-react";
import { 
  IconUser, 
  IconRobot, 
  IconSend,
  IconCode,
  IconSettings 
} from "@arco-design/web-react/icon";
import Store, { ChatMessage } from "./store";
import { ViewMarkdown } from "@/components/markdown";



const MODEL_OPTIONS = [
  { value: 'deepseek-chat', label: '通用对话' },
  { value: 'deepseek-reasoner', label: '深度思考' }
];

interface MessageItemProps {
    message: ChatMessage;
    store: Store;
}

const MessageItem = ({ message, store }: MessageItemProps) => {

    const [content, setContent] = useState(message.content);
    const [reasoningContent, setReasoningContent] = useState('');
    const [loading, setLoading] = useState(false);
    const [isText, setIsText] = useState<boolean>(false);   // 展示原文

    useEffect(() => {
        store.onScroll();
        if(message.role == 'user') return;
        setLoading(true)
        ajax.post('/deepseek/chat', {
            "model": store.model,
            aid: store.id,
            messages: [
                { role: 'user', content: message.content }
            ],
            "stream": true,
        }, {
            stream: true,
            onProgress: (text: string) => {
                setLoading(false)
                const jsonText = text.split('\n\n').map(chunk => {
                    // console.log('chunk', chunk)
                    if (chunk.startsWith('data: ')) {
                        return JSON.parse(chunk.slice(6));
                    }
                    return null;
                }).filter(item => item !== null);
                setReasoningContent(jsonText.map((o) => o.reasoning_content).join(''));
                setContent(jsonText.map((o) => o.content).join(''))
                store.onScroll();
            }
        }).finally(() => {
            setLoading(false)
        })  
    },[])
    

    return (
        <div
            key={message.timestamp}
            className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}
        >
            <div className={`flex ${message.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-start gap-3 w-full`}>
                <Avatar
                    size={40}
                    className={`shrink-0 shadow-lg ${message.role === 'user'
                            ? 'bg-blue-500 text-white'
                            : 'bg-gradient-to-br from-purple-500 to-blue-500 text-white'
                        }`}
                >
                    {message.role === 'user' ? <IconUser /> : <IconRobot />}
                </Avatar>

                <div className={`max-w-4xl p-4 rounded-2xl ${message.role === 'user'
                        ? 'bg-blue-500 text-white rounded-br-none'
                        : 'bg-white shadow-lg rounded-bl-none border border-gray-100'
                    }`}>
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium">
                            {message.role === 'user' ? '您' : MODEL_OPTIONS.find(m => m.value === message.model)?.label}
                        </span>
                        {message.role == 'ai' && (
                            <Button 
                                type={isText? 'primary' : 'default'} 
                                size="small" 
                                onClick={() => setIsText(!isText)}
                            >展示原文</Button>
                        )}
                        <span className="text-xs opacity-75 ml-2">
                            {new Date(message.timestamp).toLocaleTimeString()}
                        </span>
                    </div>
                    {reasoningContent && (
                        <div className="bg-gray-50 p-3 rounded-lg mb-3 border border-gray-200">
                            <div className="text-sm text-gray-600 font-medium mb-1">思考过程：</div>
                            <div className="text-sm text-gray-700 whitespace-pre-wrap">
                               {isText? reasoningContent : <ViewMarkdown>{reasoningContent}</ViewMarkdown>}
                            </div>
                        </div>
                    )}
                    <div className={`prose max-w-none ${message.role === 'user' ? 'text-white' : 'text-gray-800'}`}>
                        {loading? (
                            <div className="flex items-center justify-center space-x-2 py-4">
                                <Spin dot />
                                <span className="text-gray-500">正在思考中...</span>
                            </div>
                        ): isText? (
                            <div style={{ whiteSpace: 'pre-wrap' }}>
                                {content}
                            </div>
                        ): <ViewMarkdown>{content}</ViewMarkdown>
                        }
                        {/* {message.content.split('\n').map((line, i) => (
                            <p key={i} className="my-1">{line}</p>
                        ))} */}
                    </div>
                </div>
            </div>
        </div>
    )
}


export default MessageItem;